UPDATE zhixue_problem
title = #{title}, title_en = #{titleEn}, description = #{description}, input_description = #{inputDescription}, output_description = #{outputDescription}, hint = #{hint}, source = #{source}, difficulty = #{difficulty}, problem_type = #{problemType}, category_id = #{categoryId}, time_limit_ms = #{timeLimitMs}, memory_limit_mb = #{memoryLimitMb}, template_code = #{templateCode}, solution_code = #{solutionCode}, is_public = #{isPublic}, view_count = #{viewCount}, submit_count = #{submitCount}, accepted_count = #{acceptedCount}, acceptance_rate = #{acceptanceRate}, sort_order = #{sortOrder}, deleted_at = #{deletedAt}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT p.id, p.title, p.title_en, p.description, p.input_description, p.output_description,
    p.hint, p.source, p.difficulty, p.problem_type, p.category_id,
    p.time_limit_ms, p.memory_limit_mb, p.template_code, p.solution_code,
    p.is_public, p.view_count, p.submit_count, p.accepted_count,
    p.acceptance_rate, p.sort_order, p.created_by, p.created_at, p.updated_at, p.deleted_at
FROM zhixue_problem p

    INNER JOIN zhixue_problem_tag_rel ptr ON p.id = ptr.problem_id


    p.deleted_at IS NULL

        AND p.is_public = #{isPublic}


        AND p.difficulty = #{difficulty}


        AND p.category_id = #{categoryId}


        AND p.title LIKE CONCAT('%', #{search}, '%')


        AND ptr.tag_id = #{tagId}


        AND p.problem_type = #{problemType}




        ORDER BY p.submit_count DESC


        ORDER BY p.acceptance_rate DESC


        ORDER BY p.created_at DESC



    LIMIT #{offset}, #{pageSize}

SELECT COUNT(DISTINCT p.id)
FROM zhixue_problem p

    INNER JOIN zhixue_problem_tag_rel ptr ON p.id = ptr.problem_id


    p.deleted_at IS NULL

        AND p.is_public = #{isPublic}


        AND p.difficulty = #{difficulty}


        AND p.category_id = #{categoryId}


        AND p.title LIKE CONCAT('%', #{search}, '%')


        AND ptr.tag_id = #{tagId}


        AND p.problem_type = #{problemType}

SELECT p.id, p.title, p.title_en, p.description, p.input_description, p.output_description,
    p.hint, p.source, p.difficulty, p.problem_type, p.category_id,
    p.time_limit_ms, p.memory_limit_mb, p.template_code, p.solution_code,
    p.is_public, p.view_count, p.submit_count, p.accepted_count,
    p.acceptance_rate, p.sort_order, p.created_by, p.created_at, p.updated_at, p.deleted_at
FROM zhixue_problem p

    p.deleted_at IS NULL

        AND p.difficulty = #{difficulty}


        AND p.category_id = #{categoryId}


        AND p.title LIKE CONCAT('%', #{search}, '%')


        AND p.problem_type = #{problemType}


        AND p.is_public = #{isPublic}


ORDER BY p.created_at DESC

    LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM zhixue_problem p

    p.deleted_at IS NULL

        AND p.difficulty = #{difficulty}


        AND p.category_id = #{categoryId}


        AND p.title LIKE CONCAT('%', #{search}, '%')


        AND p.problem_type = #{problemType}


        AND p.is_public = #{isPublic}
